mapper.select:
SELECT user_id, MIN(id) as id FROM member_event_log WHERE event_code IN ('social_login', 'login') AND user_id IN
#{userId}
AND device_brand != '' AND (os_name = 'ios' OR os_name = 'android') GROUP BY user_id

SELECT live_code_id AS liveCodeId, COUNT(DISTINCT device_id) AS downloadCount, COUNT(DISTINCT user_id) AS downloadUserCount FROM member_event_log WHERE event_code = 'getInstall' AND live_code_id IN
#{liveCodeId}
AND live_code_id > 0 GROUP BY live_code_id

SELECT live_code_id AS liveCodeId, COUNT(*) AS downloadClickCount, COUNT(DISTINCT user_id) AS downloadClickUserCount FROM member_event_log WHERE event_code = 'app_download_click' AND live_code_id IN
#{liveCodeId}
AND live_code_id > 0 GROUP BY live_code_id

SELECT IFNULL(NULLIF(IFNULL(el.user_id, ''), 'null'), '') AS userId, mu.nickname, el.ip AS ipAddress,
case when mu.live_code_id = #{reqVO.liveCodeId} then 1 else 0 end AS isNewUser,
el.create_time AS createTime
FROM member_event_log el
LEFT JOIN member_user mu ON mu.id = el.user_id

    LEFT JOIN channel_live_code_scan_log lsl ON lsl.live_code_id = el.live_code_id

WHERE el.event_code = 'app_download_click'
  AND el.live_code_id = #{reqVO.liveCodeId}

    AND el.ip = #{reqVO.ipAddress}


    AND el.user_id = #{reqVO.userId}


    AND lsl.redirect_page like concat('%', #{reqVO.redirectPage}, '%')


    AND mu.live_code_id != #{reqVO.liveCodeId}


    AND mu.live_code_id = #{reqVO.liveCodeId}


    AND el.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

order by el.create_time desc

SELECT IFNULL(NULLIF(IFNULL(el.user_id, ''), 'null'), '') AS userId, ANY_VALUE(mu.nickname) AS nickname, MAX(el.ip) AS ipAddress,
ANY_VALUE(case when mu.live_code_id = #{reqVO.liveCodeId} then 1 else 0 end) AS isNewUser,
COUNT(*) AS clickCount, MAX(el.create_time) AS createTime
FROM member_event_log el
LEFT JOIN member_user mu ON mu.id = el.user_id

    LEFT JOIN channel_live_code_scan_log lsl ON lsl.live_code_id = el.live_code_id

WHERE el.event_code = 'app_download_click'
  AND el.live_code_id = #{reqVO.liveCodeId}

    AND el.ip = #{reqVO.ipAddress}


    AND el.user_id = #{reqVO.userId}


    AND lsl.redirect_page like concat('%', #{reqVO.redirectPage}, '%')


    AND mu.live_code_id != #{reqVO.liveCodeId}


    AND mu.live_code_id = #{reqVO.liveCodeId}


    AND el.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

GROUP BY el.user_id
order by createTime desc

SELECT el.device_id, ANY_VALUE(el.device_model) AS deviceModel, ANY_VALUE(IFNULL(NULLIF(IFNULL(el.user_id, ''), 'null'), '')) AS userId, ANY_VALUE(mu.nickname) AS nickname,
MAX(el.ip) AS ipAddress, ANY_VALUE(case when mu.live_code_id = #{reqVO.liveCodeId} then 1 else 0 end) AS isNewUser,
MAX(el.create_time) AS createTime
FROM member_event_log el
LEFT JOIN member_user mu ON mu.id = el.user_id

    LEFT JOIN channel_live_code_scan_log lsl ON lsl.live_code_id = el.live_code_id

WHERE el.event_code = 'getInstall'
  AND el.live_code_id = #{reqVO.liveCodeId}

    AND el.ip = #{reqVO.ipAddress}


    AND el.user_id = #{reqVO.userId}


    AND lsl.redirect_page like concat('%', #{reqVO.redirectPage}, '%')


    AND mu.live_code_id != #{reqVO.liveCodeId}


    AND mu.live_code_id = #{reqVO.liveCodeId}


    AND el.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

GROUP BY el.device_id
order by createTime desc

SELECT IFNULL(NULLIF(IFNULL(el.user_id, ''), 'null'), '') AS userId, ANY_VALUE(mu.nickname) AS nickname, ANY_VALUE(el.device_id) AS deviceId, ANY_VALUE(el.device_model) AS deviceModel,
MAX(el.ip) AS ipAddress, ANY_VALUE(case when mu.live_code_id = #{reqVO.liveCodeId} then 1 else 0 end) AS isNewUser,
MAX(el.create_time) AS createTime
FROM member_event_log el
LEFT JOIN member_user mu ON mu.id = el.user_id

    LEFT JOIN channel_live_code_scan_log lsl ON lsl.live_code_id = el.live_code_id

WHERE el.event_code = 'getInstall'
  AND el.live_code_id = #{reqVO.liveCodeId}

    AND el.ip = #{reqVO.ipAddress}


    AND el.user_id = #{reqVO.userId}


    AND lsl.redirect_page like concat('%', #{reqVO.redirectPage}, '%')


    AND mu.live_code_id != #{reqVO.liveCodeId}


    AND mu.live_code_id = #{reqVO.liveCodeId}


    AND el.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

GROUP BY el.user_id
order by createTime desc
